 const low=Math.min(0,Math.floor(Math.min(...values)/50)*50),high=Math.max(100,Math.ceil(Math.max(...values)/50)*50),range=Math.max(1,high-low);
 const x=i=>L+(periods.length===1?plotW/2:i*plotW/(periods.length-1));
